CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE workspace (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app_user (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, name text NOT NULL, password_hash text, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE membership (user_id uuid REFERENCES app_user(id), workspace_id uuid REFERENCES workspace(id), role text NOT NULL CHECK(role IN ('OWNER','ADMIN','MARKETER','REVIEWER','PUBLISHER','SALES','ANALYST')), brand_scope uuid[], PRIMARY KEY(user_id,workspace_id));
CREATE TABLE brand (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspace(id), name text NOT NULL, industry text NOT NULL DEFAULT '', voice text NOT NULL DEFAULT '', audience text NOT NULL DEFAULT '', color text NOT NULL DEFAULT '#6d5efc', timezone text NOT NULL DEFAULT 'Asia/Ho_Chi_Minh', enabled boolean NOT NULL DEFAULT true, mode text NOT NULL DEFAULT 'ASSISTED' CHECK(mode IN ('ASSISTED','RULED_AUTOPILOT')), policy_version int NOT NULL DEFAULT 1, version int NOT NULL DEFAULT 1, monthly_budget_micros bigint NOT NULL DEFAULT 10000000 CHECK(monthly_budget_micros>=0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,workspace_id));
CREATE TABLE brand_version (brand_id uuid NOT NULL, workspace_id uuid NOT NULL, version int NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(brand_id,version), FOREIGN KEY(brand_id,workspace_id) REFERENCES brand(id,workspace_id));
CREATE TABLE knowledge_document (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, brand_id uuid NOT NULL, title text NOT NULL, body text NOT NULL, source_url text, status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','ARCHIVED')), version int NOT NULL DEFAULT 1, effective_from timestamptz NOT NULL DEFAULT now(), effective_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,brand_id,workspace_id), FOREIGN KEY(brand_id,workspace_id) REFERENCES brand(id,workspace_id), CHECK(effective_until IS NULL OR effective_until>effective_from));
CREATE TABLE knowledge_chunk (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL, brand_id uuid NOT NULL, workspace_id uuid NOT NULL, position int NOT NULL, body text NOT NULL, search tsvector GENERATED ALWAYS AS(to_tsvector('simple',body)) STORED, FOREIGN KEY(document_id,brand_id,workspace_id) REFERENCES knowledge_document(id,brand_id,workspace_id), UNIQUE(document_id,position));
CREATE INDEX knowledge_search ON knowledge_chunk USING gin(search);
CREATE TABLE campaign (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, brand_id uuid NOT NULL, name text NOT NULL, objective text NOT NULL, pillars jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,brand_id,workspace_id), FOREIGN KEY(brand_id,workspace_id) REFERENCES brand(id,workspace_id));
CREATE TABLE content_item (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, brand_id uuid NOT NULL, campaign_id uuid, purpose text NOT NULL DEFAULT 'EDUCATION', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,brand_id,workspace_id), FOREIGN KEY(brand_id,workspace_id) REFERENCES brand(id,workspace_id), FOREIGN KEY(campaign_id,brand_id,workspace_id) REFERENCES campaign(id,brand_id,workspace_id));
CREATE TABLE content_revision (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, brand_id uuid NOT NULL, content_id uuid NOT NULL, revision_no int NOT NULL, hook text NOT NULL, body text NOT NULL, cta text NOT NULL, claims jsonb NOT NULL DEFAULT '[]', source_refs jsonb NOT NULL DEFAULT '[]', risk_flags jsonb NOT NULL DEFAULT '[]', creative_brief jsonb NOT NULL DEFAULT '{}', snapshot_hash text NOT NULL, status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','IN_REVIEW','APPROVED','CHANGES_REQUESTED','ARCHIVED')), created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(content_id,revision_no), UNIQUE(id,brand_id,workspace_id), FOREIGN KEY(content_id,brand_id,workspace_id) REFERENCES content_item(id,brand_id,workspace_id));
CREATE TABLE approval (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, brand_id uuid NOT NULL, revision_id uuid NOT NULL, policy_version int NOT NULL, snapshot_hash text NOT NULL, actor text NOT NULL, decision text NOT NULL CHECK(decision IN ('APPROVED','CHANGES_REQUESTED')), note text NOT NULL DEFAULT '', valid_until timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(revision_id,brand_id,workspace_id) REFERENCES content_revision(id,brand_id,workspace_id));
CREATE TABLE social_account (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, brand_id uuid NOT NULL, provider text NOT NULL CHECK(provider IN ('DEMO','META')), remote_id text NOT NULL, name text NOT NULL, token_ciphertext text, health text NOT NULL DEFAULT 'CONNECTED', permissions jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,brand_id,workspace_id), UNIQUE(workspace_id,provider,remote_id), FOREIGN KEY(brand_id,workspace_id) REFERENCES brand(id,workspace_id));
CREATE TABLE publication (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, brand_id uuid NOT NULL, revision_id uuid NOT NULL, account_id uuid NOT NULL, intent text NOT NULL, due_at timestamptz NOT NULL, deadline_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'QUEUED' CHECK(status IN ('QUEUED','DISPATCHING','PUBLISHED','RETRY_WAIT','UNKNOWN','BLOCKED','FAILED','CANCELLED')), snapshot jsonb NOT NULL, snapshot_hash text NOT NULL, policy_version int NOT NULL, operation_key uuid NOT NULL DEFAULT gen_random_uuid(), remote_post_id text, remote_url text, published_at timestamptz, last_error text, version int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,revision_id,account_id,intent), UNIQUE(id,brand_id,workspace_id), FOREIGN KEY(revision_id,brand_id,workspace_id) REFERENCES content_revision(id,brand_id,workspace_id), FOREIGN KEY(account_id,brand_id,workspace_id) REFERENCES social_account(id,brand_id,workspace_id));
CREATE INDEX publications_calendar ON publication(workspace_id,brand_id,due_at,id);
CREATE TABLE workflow_run (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, brand_id uuid NOT NULL, campaign_id uuid, topic text NOT NULL, workflow_version text NOT NULL DEFAULT '1.0', brand_version int NOT NULL, policy_version int NOT NULL, status text NOT NULL DEFAULT 'QUEUED', step int NOT NULL DEFAULT 0, output_revision_id uuid, error text, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,brand_id,workspace_id), FOREIGN KEY(brand_id,workspace_id) REFERENCES brand(id,workspace_id), FOREIGN KEY(campaign_id,brand_id,workspace_id) REFERENCES campaign(id,brand_id,workspace_id), FOREIGN KEY(output_revision_id,brand_id,workspace_id) REFERENCES content_revision(id,brand_id,workspace_id));
CREATE TABLE step_run (run_id uuid REFERENCES workflow_run(id), step int NOT NULL, name text NOT NULL, status text NOT NULL, output jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(run_id,step));
CREATE TABLE job (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, brand_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('GENERATE','PUBLISH','METRICS','WEBHOOK')), aggregate_id uuid NOT NULL, status text NOT NULL DEFAULT 'READY' CHECK(status IN ('READY','RUNNING','DONE','FAILED')), due_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, owner text, fence bigint NOT NULL DEFAULT 0, attempts int NOT NULL DEFAULT 0, last_error text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kind,aggregate_id,due_at), FOREIGN KEY(brand_id,workspace_id) REFERENCES brand(id,workspace_id));
CREATE INDEX job_due ON job(due_at,id) WHERE status='READY';
CREATE TABLE publication_attempt (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), publication_id uuid REFERENCES publication(id), job_id uuid REFERENCES job(id), fencing_token bigint NOT NULL, outcome text NOT NULL DEFAULT 'STARTED', provider_request_id text, error_code text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency (workspace_id uuid NOT NULL REFERENCES workspace(id), scope text NOT NULL, key text NOT NULL, request_hash text NOT NULL, resource_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,scope,key));
CREATE TABLE budget_month (workspace_id uuid NOT NULL, brand_id uuid NOT NULL, month date NOT NULL, reserved_micros bigint NOT NULL DEFAULT 0, spent_micros bigint NOT NULL DEFAULT 0, PRIMARY KEY(brand_id,month), FOREIGN KEY(brand_id,workspace_id) REFERENCES brand(id,workspace_id), CHECK(reserved_micros>=0 AND spent_micros>=0));
CREATE TABLE budget_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, brand_id uuid NOT NULL, run_id uuid NOT NULL UNIQUE REFERENCES workflow_run(id), month date NOT NULL, reserved_micros bigint NOT NULL, charged_micros bigint, status text NOT NULL DEFAULT 'RESERVED', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(brand_id,workspace_id) REFERENCES brand(id,workspace_id));
CREATE TABLE ai_run (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, brand_id uuid NOT NULL, run_id uuid NOT NULL UNIQUE REFERENCES workflow_run(id), provider text NOT NULL, model text NOT NULL, prompt_version text NOT NULL, input_refs jsonb NOT NULL, output jsonb NOT NULL, input_tokens int, output_tokens int, usage_status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(brand_id,workspace_id) REFERENCES brand(id,workspace_id));
CREATE TABLE lead (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, brand_id uuid NOT NULL, name text NOT NULL, contact text NOT NULL, interest text NOT NULL DEFAULT '', stage text NOT NULL DEFAULT 'NEW' CHECK(stage IN ('NEW','QUALIFIED','CONTACTED','WON','LOST','DISQUALIFIED')), source_publication_id uuid, attribution_confidence text NOT NULL DEFAULT 'UNKNOWN' CHECK(attribution_confidence IN ('EXACT','INFERRED','UNKNOWN')), purpose text NOT NULL, consent_at timestamptz NOT NULL, consent_version text NOT NULL, assigned_user text, next_action text, version int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(brand_id,workspace_id) REFERENCES brand(id,workspace_id), FOREIGN KEY(source_publication_id,brand_id,workspace_id) REFERENCES publication(id,brand_id,workspace_id));
CREATE INDEX lead_list ON lead(workspace_id,brand_id,created_at DESC,id DESC);
CREATE TABLE lead_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid REFERENCES lead(id), actor text NOT NULL, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE metric_snapshot (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, brand_id uuid NOT NULL, publication_id uuid NOT NULL, metric_name text NOT NULL, value numeric, unit text NOT NULL DEFAULT 'count', definition text NOT NULL, missing_reason text, provider text NOT NULL, window_hours int NOT NULL, fetched_at timestamptz NOT NULL DEFAULT now(), UNIQUE(publication_id,metric_name,window_hours), FOREIGN KEY(publication_id,brand_id,workspace_id) REFERENCES publication(id,brand_id,workspace_id));
CREATE TABLE outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspace(id), brand_id uuid NOT NULL, event_type text NOT NULL, aggregate_id uuid NOT NULL, schema_version int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, FOREIGN KEY(brand_id,workspace_id) REFERENCES brand(id,workspace_id));
CREATE TABLE inbox_event (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, brand_id uuid NOT NULL, account_id uuid NOT NULL, fingerprint text NOT NULL UNIQUE, payload jsonb NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, FOREIGN KEY(account_id,brand_id,workspace_id) REFERENCES social_account(id,brand_id,workspace_id));
CREATE TABLE audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspace(id), brand_id uuid, actor text NOT NULL, action text NOT NULL, aggregate_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_list ON audit_log(workspace_id,created_at DESC);
CREATE FUNCTION prevent_revision_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF (to_jsonb(NEW)-'status') IS DISTINCT FROM (to_jsonb(OLD)-'status') THEN RAISE EXCEPTION 'Content revisions are immutable'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER immutable_revision BEFORE UPDATE ON content_revision FOR EACH ROW EXECUTE FUNCTION prevent_revision_mutation();
